    /// - Remark: Generated from `#/paths//system/metrics/get(getMetrics)`.
    public func getMetrics(headers: Operations.GetMetrics.Input.Headers = .init()) async throws -> Operations.GetMetrics.Output {
        try await getMetrics(Operations.GetMetrics.Input(headers: headers))
    }
    /// Liveness/readiness probe.
    ///
    /// - Remark: HTTP `GET /system/health`.
    /// - Remark: Generated from `#/paths//system/health/get(getHealth)`.
    public func getHealth(headers: Operations.GetHealth.Input.Headers = .init()) async throws -> Operations.GetHealth.Output {
        try await getHealth(Operations.GetHealth.Input(headers: headers))
    }
    /// First-run setup. Creates the admin account. Only allowed while setupRequired is true.
    ///
    /// - Remark: HTTP `POST /setup`.
    /// - Remark: Generated from `#/paths//setup/post(completeSetup)`.
